<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';
use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
SchoolAuth::requireLogin();$user=SchoolAuth::user();$role=school_current_role($user);if(!SchoolAuth::hasPermission('finance.view')){http_response_code(403);exit('Finance access is not permitted.');}$invoiceId=(int)($_GET['invoice_id']??0);$pdo=SchoolDatabase::connection();
$q=$pdo->prepare('SELECT i.id,i.invoice_number,i.status,i.issued_at,i.due_at,s.id student_id,s.admission_number,s.full_name,t.name term_name,y.name year_name,pf.name school_name,pf.address,pf.phone,pf.email FROM invoices i JOIN students s ON s.id=i.student_id JOIN terms t ON t.id=i.term_id JOIN academic_years y ON y.id=t.academic_year_id LEFT JOIN school_profile pf ON pf.id=(SELECT MIN(id) FROM school_profile) WHERE i.id=:id');$q->execute(['id'=>$invoiceId]);$invoice=$q->fetch();if(!$invoice){http_response_code(404);exit('Invoice not found.');}
if($role==='parent_guardian'&&!SchoolAuth::can('portal.child',['student_id'=>(int)$invoice['student_id']])){http_response_code(403);exit('You are not permitted to view this invoice.');}if($role==='student'&&!SchoolAuth::can('portal.self',['student_id'=>(int)$invoice['student_id']])){http_response_code(403);exit('You are not permitted to view this invoice.');}
$q=$pdo->prepare('SELECT description,amount,discount FROM invoice_items WHERE invoice_id=:id ORDER BY id');$q->execute(['id'=>$invoiceId]);$items=$q->fetchAll();$q=$pdo->prepare("SELECT p.id,p.amount,p.method,p.reference,p.created_at,pa.amount allocated FROM payment_allocations pa JOIN payments p ON p.id=pa.payment_id WHERE pa.invoice_id=:id AND p.status='succeeded' ORDER BY p.created_at,p.id");$q->execute(['id'=>$invoiceId]);$payments=$q->fetchAll();$total=0.0;$paid=0.0;foreach($items as $item)$total+=(float)$item['amount']-(float)$item['discount'];foreach($payments as $payment)$paid+=(float)$payment['allocated'];$balance=max(0,$total-$paid);$schoolName=(string)($invoice['school_name']?:'School Management');$pageTitle='Invoice '.$invoice['invoice_number'];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?></title><link rel="stylesheet" href="<?= SCHOOL_ASSET_URL ?>vendor/bootstrap.min.css"><link rel="stylesheet" href="<?= SCHOOL_ASSET_URL ?>vendor/bootstrap-icons.css"><link rel="stylesheet" href="<?= SCHOOL_ASSET_URL ?>css/style.css"><link rel="stylesheet" href="<?= SCHOOL_ASSET_URL ?>css/lms.css"><style>.receipt-sheet{max-width:900px;margin:28px auto;padding:34px;background:#fff}.receipt-brand{border-bottom:2px solid var(--primary,#0b684f);padding-bottom:18px;margin-bottom:24px}.receipt-total{max-width:360px;margin-left:auto}@media print{body{background:#fff!important}.sidebar,.topbar,.app-footer,.page-head,.no-print{display:none!important}.main{margin:0!important;padding:0!important}.content{padding:0!important}.receipt-sheet{max-width:none;margin:0;padding:0;box-shadow:none;border:0!important}.card{box-shadow:none!important;border:0!important}.receipt-brand{border-color:#222}}</style></head><body><div class="receipt-sheet card border-0 shadow-sm"><div class="d-flex justify-content-between align-items-start receipt-brand"><div><h3 class="mb-1"><?= e($schoolName) ?></h3><?php if($invoice['address']): ?><div class="small text-muted"><?= e($invoice['address']) ?></div><?php endif; ?><div class="small text-muted"><?= e(implode(' · ',array_filter([$invoice['phone'],$invoice['email']]))) ?></div></div><div class="text-end"><span class="badge bg-success-subtle text-success">SCHOOL INVOICE</span><h5 class="mt-2 mb-1"><?= e($invoice['invoice_number']) ?></h5><div class="small text-muted">Issued <?= e(formatDate(substr((string)$invoice['issued_at'],0,10))) ?></div></div></div><div class="row mb-4"><div class="col-md-6"><div class="small text-muted">Billed to</div><strong><?= e($invoice['full_name']) ?></strong><div><?= e($invoice['admission_number']) ?></div></div><div class="col-md-6 text-md-end"><div class="small text-muted">Academic period</div><strong><?= e($invoice['year_name'].' · '.$invoice['term_name']) ?></strong><div class="small text-muted">Due <?= e(formatDate($invoice['due_at'])) ?></div></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Description</th><th class="text-end">Amount</th><th class="text-end">Discount</th><th class="text-end">Line total</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= e($item['description']) ?></td><td class="text-end"><?= e(money($item['amount'])) ?></td><td class="text-end"><?= e(money($item['discount'])) ?></td><td class="text-end"><?= e(money((float)$item['amount']-(float)$item['discount'])) ?></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="4" class="text-center text-muted">No invoice lines</td></tr><?php endif; ?></tbody></table></div><div class="receipt-total"><div class="d-flex justify-content-between py-1"><span>Invoice total</span><strong><?= e(money($total)) ?></strong></div><div class="d-flex justify-content-between py-1"><span>Payments received</span><strong><?= e(money($paid)) ?></strong></div><div class="d-flex justify-content-between border-top mt-1 pt-2 fs-5"><span>Balance</span><strong><?= e(money($balance)) ?></strong></div></div><h6 class="mt-4">Payment history</h6><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Receipt</th><th>Date</th><th>Method</th><th>Reference</th><th class="text-end">Amount</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr><td>RCPT-<?= (int)$payment['id'] ?></td><td><?= e(formatDate(substr((string)$payment['created_at'],0,10))) ?></td><td><?= e(str_replace('_',' ',$payment['method'])) ?></td><td><?= e($payment['reference']?:'—') ?></td><td class="text-end"><?= e(money($payment['allocated'])) ?></td></tr><?php endforeach; ?><?php if(!$payments): ?><tr><td colspan="5" class="text-center text-muted">No payments recorded.</td></tr><?php endif; ?></tbody></table></div><p class="small text-muted mt-4">This document reflects school records as of <?= e(date('d/m/Y H:i')) ?>. Please contact the school office if you believe an entry is incorrect.</p><div class="no-print d-flex gap-2"><a class="btn btn-outline-primary" href="<?= SCHOOL_BASE_URL ?>reports/pdf.php?type=invoice&amp;invoice_id=<?= (int) $invoiceId ?>"><i class="bi bi-file-earmark-pdf me-1"></i>Download PDF</a><button class="btn btn-primary" onclick="window.print()"><i class="bi bi-printer me-1"></i>Print / Save as PDF</button><button class="btn btn-outline-secondary" onclick="history.back()">Back</button></div></div></body></html>
